import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Kubernetes 生产运维：发布、容量与数据保护","description":"将生产就绪清单与现有变更、RBAC、恢复步骤集中。","frontmatter":{"title":"Kubernetes 生产运维：发布、容量与数据保护","description":"将生产就绪清单与现有变更、RBAC、恢复步骤集中。","showdocs":{"topics":[{"id":"kubernetes","title":"Kubernetes","link":"/topics/kubernetes/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Kubernetes机制与应用理论课程","summary":"将生产就绪清单与现有变更、RBAC、恢复步骤集中。","status":"active","related":[{"title":"Kubernetes 操作与命令","link":"/systems/kubernetes/plus/ecosystem/kubernetes-general-general","kind":"命令","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储","link":"/systems/kubernetes/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储 · 按 Pod、Service 与端点定位故障至Pod 运行但服务不可达的复盘","link":"/systems/kubernetes/troubleshooting-part-02","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储 · Kubernetes 排障手册","link":"/systems/kubernetes/troubleshooting-part-01","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes：部署配置、服务身份与持久卷","link":"/systems/kubernetes/plus/practice/application","kind":"实践","scope":"general","audience":"general"}],"prev":{"text":"Kubernetes：部署配置、服务身份与持久卷","link":"/systems/kubernetes/plus/practice/application"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Kubernetes：部署配置、服务身份与持久卷","link":"/systems/kubernetes/plus/practice/application"},"next":false},"headers":[],"relativePath":"systems/kubernetes/operations.md","filePath":"systems/kubernetes/operations.md"}'),l={name:"systems/kubernetes/operations.md"};function s(n,e,o,c,p,u){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="kubernetes-生产运维-发布、容量与数据保护" tabindex="-1">Kubernetes 生产运维：发布、容量与数据保护 <a class="header-anchor" href="#kubernetes-生产运维-发布、容量与数据保护" aria-label="Permalink to &quot;Kubernetes 生产运维：发布、容量与数据保护&quot;">​</a></h1><h2 id="part-1" tabindex="-1">发布回滚、权限与集群维护 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;发布回滚、权限与集群维护 {#part-1}&quot;">​</a></h2><p>维护Kubernetes 单副本计数项目前先保存context、namespace、Secret 与 PVC，恢复后以Pod 条件、EndpointSlice 与持久数据验收。具体配置见<a href="/systems/kubernetes/plus/practice/application#manifests">配套示例</a>。</p><h3 id="part-1-release" tabindex="-1">配置发布与回滚 <a class="header-anchor" href="#part-1-release" aria-label="Permalink to &quot;配置发布与回滚 {#part-1-release}&quot;">​</a></h3><p>Kubernetes 配置 更新不是同时发生的事务。本例 ConfigMap 进入环境变量，Secret 在进程启动时读入；对象更新后旧进程仍保存旧值。应将配置变更与 PodTemplate 修订关联，用校验和注解或受控 rollout 明确重建，并记录配置版本、镜像 digest 和数据库兼容性。</p><p>Deployment rollback 主要回到旧 PodTemplate，不恢复外部 ConfigMap、Secret 或 PVC 数据。若两个修订引用同一个可变 ConfigMap 名称，旧模板也可能拿到新配置。生产可使用版本化配置对象，保留旧版本直到确认不再需要，并规划 Secret 轮换的双凭据过渡。</p><h3 id="part-1-rbac" tabindex="-1">RBAC 与身份 <a class="header-anchor" href="#part-1-rbac" aria-label="Permalink to &quot;RBAC 与身份 {#part-1-rbac}&quot;">​</a></h3><p>Kubernetes RBAC 最小权限 由 Role 的资源/verb 与 RoleBinding 的主体共同决定。RBAC 只有允许规则，多条绑定权限取并集；命名空间内 RoleBinding 绑定 ClusterRole 也不会把该角色授予整个集群。认证、鉴权和准入是不同阶段，允许创建 Pod 不代表准入一定接受。</p><p>主例 counter ServiceAccount 不调用 API，故 automountServiceAccountToken: false；不能为了应用访问自己的数据卷而授 cluster-admin。observer 只读资源和日志，不读 secrets、不 exec、不改 Deployment。拥有创建 Pod、修改 RoleBinding 或模拟身份的权限可能形成间接提权，应按真实任务评估，而不是只看是否显式有 get secrets。</p><h3 id="part-1-capacity" tabindex="-1">容量、扩缩与故障域 <a class="header-anchor" href="#part-1-capacity" aria-label="Permalink to &quot;容量、扩缩与故障域 {#part-1-capacity}&quot;">​</a></h3><p>Kubernetes HPA requests 必须匹配指标语义：按 CPU 利用率伸缩通常需要 requests 和资源指标源；HPA 增副本不等于节点容量自动增加，节点扩容也不修复单写数据库设计。本例不含 HPA，因为 SQLite 单副本并不是可水平扩展后端。</p><p>资源值需依据启动、峰值、稳定期、重试与故障恢复测量。跨节点或故障域的拓扑分布、PDB、亲和性与配额会限制调度和维护。PDB 约束自愿中断，但不保证硬件故障时有副本，也不消除 drain 可能长时间等待的情况。</p><h3 id="part-1-backup" tabindex="-1">卷、快照与集群维护 <a class="header-anchor" href="#part-1-backup" aria-label="Permalink to &quot;卷、快照与集群维护 {#part-1-backup}&quot;">​</a></h3><p>Kubernetes PVC 备份 不由 etcd 快照代替：etcd 保存 API 对象，应用实际文件在后端存储。CSI 快照能力取决于驱动与控制器，快照是否应用一致还需数据库协调。恢复到新 PVC 后先核对数据、权限、应用版本与恢复时点，再切换服务，不能把“快照资源创建成功”写成恢复已验证。</p><p>集群升级需核对服务端/客户端版本偏差、API 移除、CNI/CSI/准入 webhook 和 CRD 兼容；节点维护先确认容量与 PDB，再计划 cordon/drain。drain 的 delete-emptydir-data 和强制选项可能丢临时状态，不能作为通用排障起手式。托管平台与自建 kubeadm 的控制面责任不同，命令不可混用。</p><h3 id="part-1-exercise" tabindex="-1">维护练习与解答 <a class="header-anchor" href="#part-1-exercise" aria-label="Permalink to &quot;维护练习与解答 {#part-1-exercise}&quot;">​</a></h3><p>问题：回滚 Deployment 后 MESSAGE 仍是新值，是否回滚失败？答案：可能模板已经回退，但仍引用同名新 ConfigMap。检查模板修订和配置对象两条线，不能只重复 rollback。</p><p>问题：平台备份了 etcd 能恢复 count 吗？答案：不能据此保证，count 位于 PVC 后端，需要应用一致的数据备份与真实恢复验证。</p><p>深入手册：<a href="/systems/kubernetes/plus/subjects/12-autoscaling">扩缩容</a>、<a href="/systems/kubernetes/plus/subjects/13-security-rbac">安全 RBAC</a>、<a href="/systems/kubernetes/observability#part-1">可观测性</a>、<a href="/systems/kubernetes/plus/subjects/16-upgrade-maintenance">升级维护</a>、<a href="#part-2">生产实践</a>。一手依据：<a href="https://kubernetes.io/docs/reference/access-authn-authz/rbac/" target="_blank" rel="noopener noreferrer">RBAC</a>、<a href="https://kubernetes.io/docs/concepts/configuration/configmap/" target="_blank" rel="noopener noreferrer">ConfigMap</a>、<a href="https://kubernetes.io/docs/concepts/configuration/secret/" target="_blank" rel="noopener noreferrer">Secrets</a>、<a href="https://kubernetes.io/docs/concepts/workloads/pods/disruptions/" target="_blank" rel="noopener noreferrer">Disruptions</a>。核对 2026-10-17。</p><h3 id="part-1-legacy-containers-admin-ui-resource-boundaries" tabindex="-1">管理界面的权限、网络与存储审查 <a class="header-anchor" href="#part-1-legacy-containers-admin-ui-resource-boundaries" aria-label="Permalink to &quot;管理界面的权限、网络与存储审查 {#part-1-legacy-containers-admin-ui-resource-boundaries}&quot;">​</a></h3><p>Kubernetes 管理界面使用 cluster-admin、hostNetwork 和 hostPath 时要检查什么？ 管理界面是集群内的应用，也要沿身份、网络和数据三条线审查。Kuboard v3 旧清单把 ServiceAccount 绑定 cluster-admin，给 etcd DaemonSet 使用 hostNetwork、hostPort 与 hostPath，并用节点亲和与容忍选择节点。需要分别解释它为何需要这些权限、实际会在哪些节点保存数据，以及服务端口与 agent TCP/UDP 端口的调用方；浏览器能访问 NodePort 只覆盖入口，不证明 agent 通信、数据库可靠性或授权边界。</p><p>不要由“DaemonSet 跑在多个节点”推导数据已可靠复制，也不要把原节点目录当作可移植的 PVC。评估替代版本时，应查看目标产品的实际部署与备份合同，再按任务授予权限、确认网络可达和恢复路径。本课 observer 只读角色不是该管理界面的等价替换；这里继承审查方法，原厂商清单和原地址不再作为可执行指导。<a href="https://kubernetes.io/docs/reference/access-authn-authz/rbac/" target="_blank" rel="noopener noreferrer">RBAC</a>与<a href="https://kubernetes.io/docs/concepts/storage/volumes/" target="_blank" rel="noopener noreferrer">卷</a>是平台侧核对依据。</p><h3 id="part-1-legacy-containers-pki-file-dependency-review" tabindex="-1">从证书脚本检查文件与信任链 <a class="header-anchor" href="#part-1-legacy-containers-pki-file-dependency-review" aria-label="Permalink to &quot;从证书脚本检查文件与信任链 {#part-1-legacy-containers-pki-file-dependency-review}&quot;">​</a></h3><p>如何从 Kubernetes 二进制部署草稿发现证书路径和 etcd 协议不一致？ 二进制部署草稿适合练习“生成什么、消费什么”的静态核对。原稿生成 ca-ssl.json 却引用 ca-config.json，覆盖 etcd-csr.json 后又读取未生成的 kube-apiserver-csr.json；复制 .pem 产物后，API Server 参数却指向 ca.crt、apiserver.crt 等另一组文件。仅把脚本排版变整齐，不会补齐这些依赖。先画出 CA→CSR→签发产物→服务参数的对应表，逐项核对路径、证书用途、SAN、私钥访问权与有效期，再检查组件之间是否信任同一个签发链。<a href="https://kubernetes.io/docs/setup/best-practices/certificates/" target="_blank" rel="noopener noreferrer">PKI requirements</a>为核对入口（2026-10-17）。</p><p>协议也属于合同：原 etcd 监听和通告使用 HTTPS，API Server 却连接 HTTP；这不是靠重试可修复的同一个地址。etcd 客户端与 peer 连接要分别确认监听、通告、信任 CA 和客户端证书。旧参数还包含未提供的 service-account/front-proxy/kubelet-client 文件，因此没有闭合到可运行集群。本节只保存审查方法和具体断点；没有生成证书、运行 cfssl/systemd、补写安装脚本或声称兼容当前版本。</p><h2 id="part-2" tabindex="-1">Kubernetes 生产实践 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;Kubernetes 生产实践 {#part-2}&quot;">​</a></h2><h3 id="part-2-生产就绪不是一个-yaml" tabindex="-1">生产就绪不是一个 YAML <a class="header-anchor" href="#part-2-生产就绪不是一个-yaml" aria-label="Permalink to &quot;生产就绪不是一个 YAML {#part-2-生产就绪不是一个-yaml}&quot;">​</a></h3><p>生产 Kubernetes 是控制面、节点、插件、云资源、镜像仓库、身份、可观测性和团队流程共同组成的系统。下面是基线，不替代发行版与业务专用设计。</p><h3 id="part-2-集群与故障域" tabindex="-1">集群与故障域 <a class="header-anchor" href="#part-2-集群与故障域" aria-label="Permalink to &quot;集群与故障域 {#part-2-集群与故障域}&quot;">​</a></h3><ul><li>控制面跨故障域高可用；etcd 使用低延迟、可靠磁盘并定期恢复演练。</li><li>工作节点至少跨多个故障域，关键服务多副本并用拓扑分布。</li><li>CoreDNS、CNI、CSI、Ingress/Gateway、监控和密钥控制器同样多副本。</li><li>预留单节点/单故障域失败、滚动升级和突发扩容容量。</li><li>明确单集群、同区域多集群或跨区域架构；Kubernetes 不自动提供跨集群容灾。</li></ul><h3 id="part-2-命名空间与多租户" tabindex="-1">命名空间与多租户 <a class="header-anchor" href="#part-2-命名空间与多租户" aria-label="Permalink to &quot;命名空间与多租户 {#part-2-命名空间与多租户}&quot;">​</a></h3><p>按团队/环境/生命周期划分命名空间，配套：</p><ul><li>专用 ServiceAccount 和最小 RBAC。</li><li>ResourceQuota、LimitRange 和 PriorityClass 治理。</li><li>默认拒绝 NetworkPolicy 与明确出口。</li><li>Pod Security Admission 和准入策略。</li><li>成本、告警、备份、所有者和数据等级标签。</li></ul><p>命名空间不是强隔离沙箱。互不信任租户应评估独立节点池、RuntimeClass、用户命名空间、沙箱运行时甚至独立集群。</p><h3 id="part-2-工作负载生产基线" tabindex="-1">工作负载生产基线 <a class="header-anchor" href="#part-2-工作负载生产基线" aria-label="Permalink to &quot;工作负载生产基线 {#part-2-工作负载生产基线}&quot;">​</a></h3><p>每个服务还应具备：</p><ul><li>稳定标签、Owner、Runbook、SLO、Dashboard 和告警。</li><li>镜像 digest、SBOM、扫描、签名/来源验证和回退版本。</li><li>多副本、PDB、拓扑分布、资源请求、三类探针、优雅终止和连接排空。</li><li>非 root、禁止提权、只读根文件系统、默认 seccomp 和最小 capabilities。</li><li>配置 Schema、Secret 轮换和向前/向后兼容发布。</li><li>应用级日志、指标、Trace 和健康端点。</li></ul><h3 id="part-2-发布治理" tabindex="-1">发布治理 <a class="header-anchor" href="#part-2-发布治理" aria-label="Permalink to &quot;发布治理 {#part-2-发布治理}&quot;">​</a></h3><ol><li>代码、清单、Chart/Overlay 和策略均经 Review。</li><li>CI 执行单测、镜像构建/扫描、Schema、服务器 dry-run/策略和集成测试。</li><li>CD 展示 diff，使用独立最小权限身份，等待 rollout 和业务冒烟。</li><li>高风险服务用金丝雀/蓝绿与自动指标判定；数据库先做兼容迁移。</li><li>变更与监控时间线关联，失败自动停止扩散而不是无限重试。</li><li>紧急手工修改必须记录并尽快回写声明式源，消除漂移。</li></ol><p>GitOps/Helm/Kustomize 是配置交付工具，不自动保证配置正确。明确每个字段的唯一管理者，避免 HPA、GitOps、人工同时写 <code>replicas</code>。</p><h3 id="part-2-容量与弹性" tabindex="-1">容量与弹性 <a class="header-anchor" href="#part-2-容量与弹性" aria-label="Permalink to &quot;容量与弹性 {#part-2-容量与弹性}&quot;">​</a></h3><ul><li>requests 基于真实负载，定期对比使用率与节流/OOM。</li><li>命名空间 Quota 留出 surge、故障恢复、Job 和调试余量。</li><li>HPA 上限与下游数据库、缓存、消息队列容量一致。</li><li>节点扩容考虑启动延迟、云配额、IP、镜像拉取和 PV 故障域。</li><li>定期演练节点、故障域、DNS、Registry、依赖和控制面故障。</li><li>避免所有关键副本被同一节点、节点池或可用区承载。</li></ul><h3 id="part-2-数据保护" tabindex="-1">数据保护 <a class="header-anchor" href="#part-2-数据保护" aria-label="Permalink to &quot;数据保护 {#part-2-数据保护}&quot;">​</a></h3><ul><li>为每个有状态系统定义 RPO、RTO、备份所有者、保留与恢复流程。</li><li>数据库使用应用一致备份；CSI 快照只是其中一个层次。</li><li>备份存储与集群/账户/区域隔离，启用加密和防删除。</li><li>定期恢复到隔离环境并验证业务数据，而不是只验证文件存在。</li><li>记录 PVC、PV、后端卷、StatefulSet 序号和数据库成员映射。</li><li>etcd 备份只保护 Kubernetes API 状态，不替代业务数据备份。</li></ul><h3 id="part-2-安全运营" tabindex="-1">安全运营 <a class="header-anchor" href="#part-2-安全运营" aria-label="Permalink to &quot;安全运营 {#part-2-安全运营}&quot;">​</a></h3><ul><li>人员通过集中身份/OIDC 和短期权限访问，不共享 kubeconfig。</li><li>Break-glass 凭据离线保护、使用即告警、事后轮换和复盘。</li><li>节点与控制面无不必要公网入口，补丁在支持窗口内上线。</li><li>审计 exec、Secret、RBAC、Webhook、CRD、Node 和策略变更。</li><li>第三方 Chart/Operator 视为软件供应链依赖，审查权限与维护状态。</li><li>建立 Kubernetes、CNI/CSI、Ingress、运行时和 OS CVE 响应流程。</li></ul><h3 id="part-2-可观测性与值班" tabindex="-1">可观测性与值班 <a class="header-anchor" href="#part-2-可观测性与值班" aria-label="Permalink to &quot;可观测性与值班 {#part-2-可观测性与值班}&quot;">​</a></h3><ul><li>以用户 SLO 驱动告警，基础设施告警能关联业务影响。</li><li>Dashboard 可按 cluster → namespace → workload → Pod → node 下钻。</li><li>日志、指标、Trace、Event、Audit 与部署版本使用统一时间和元数据。</li><li>Runbook 给出只读诊断、决策点、安全缓解、回退和升级路径。</li><li>每季度通过游戏日/故障演练验证人、权限、工具和文档。</li></ul><h3 id="part-2-成本治理" tabindex="-1">成本治理 <a class="header-anchor" href="#part-2-成本治理" aria-label="Permalink to &quot;成本治理 {#part-2-成本治理}&quot;">​</a></h3><ul><li>以 requests/实际使用/峰值对比发现闲置和风险，而非只看账单总额。</li><li>分配共享控制面、LB、公网流量、日志、快照和闲置 PV 成本。</li><li>Spot/抢占式节点只承载可中断、跨节点冗余且有恢复能力的工作负载。</li><li>节省成本不能破坏 N+1 容量、发布 Surge 或灾备目标。</li></ul><h3 id="part-2-生命周期治理" tabindex="-1">生命周期治理 <a class="header-anchor" href="#part-2-生命周期治理" aria-label="Permalink to &quot;生命周期治理 {#part-2-生命周期治理}&quot;">​</a></h3><p>建立版本台账：Kubernetes、节点 OS、运行时、CNI、CSI、DNS、Ingress/Gateway、监控、Operator、CRD 与客户端。每项记录当前版、目标版、EOL、Owner、兼容矩阵和升级演练日期。</p><p>每个次要版本发布后：</p><ol><li>阅读公告、弃用和安全变化。</li><li>在预发运行 API/插件兼容测试。</li><li>升到当前分支最新补丁，减少已知缺陷。</li><li>在 EOL 前完成逐级升级，不把多个大版本堆到最后。</li></ol><h3 id="part-2-生产评审清单" tabindex="-1">生产评审清单 <a class="header-anchor" href="#part-2-生产评审清单" aria-label="Permalink to &quot;生产评审清单 {#part-2-生产评审清单}&quot;">​</a></h3><ul><li>[ ] 服务 SLO、Owner、Runbook、Dashboard、告警齐全。</li><li>[ ] 多副本跨故障域，PDB、资源、探针和优雅终止已压测。</li><li>[ ] RBAC、Pod Security、NetworkPolicy、镜像和 Secret 达到基线。</li><li>[ ] 配置/Schema/依赖支持滚动发布与回退。</li><li>[ ] HPA/节点容量/配额/IP/PV 能覆盖峰值与故障。</li><li>[ ] 备份跨故障域且恢复演练满足 RPO/RTO。</li><li>[ ] 发布、紧急变更和 Break-glass 流程实际演练过。</li><li>[ ] 核心与插件版本均在支持期，升级窗口明确。</li></ul>',56)])])}const b=a(l,[["render",s]]);export{h as __pageData,b as default};
